function scoringResumeAI(kontenResume) { const kriteria = ambilKriteria(); const isiTeks = kontenResume.teks || '(Konten tidak tersedia)'; const prompt = `Kamu adalah sistem HR AI. Analisis resume berikut.
Posisi: ${CONFIG.POSISI}
Kriteria penilaian:
${kriteria}
Resume kandidat:
${isiTeks}
Balas HANYA dengan JSON valid seperti ini (tanpa markdown, tanpa teks lain):
{
  skor: 75,
  kekurangan: Tidak ada pengalaman SQL dan visualisasi data,
  ringkasan: Kandidat memiliki 2 tahun pengalaman sebagai data analyst
}`; try { const url = 'https://api.groq.com/openai/v1/chat/completions'; const payload = { model: CONFIG.GROQ_MODEL, messages: [{ role: 'system', content: 'Kamu adalah sistem HR AI. Balas HANYA dalam format JSON valid tanpa markdown.' }, { role: 'user', content: prompt }], temperature: 0.1, max_tokens: 500 }; const response = UrlFetchApp.fetch(url, { method: 'POST', headers: { 'Authorization': 'Bearer ' + CONFIG.GROQ_API_KEY, 'Content-Type': 'application/json' }, payload: JSON.stringify(payload), muteHttpExceptions: true }); const responseCode = response.getResponseCode(); const responseText = response.getContentText(); if (responseCode !== 200) { return { skor: 0, kekurangan: `Error API: ${responseCode}`, ringkasan: '-' }; } const data = JSON.parse(responseText); let teks = data.choices[0].message.content; teks = teks.replace(/```json|```/g, '').trim(); return JSON.parse(teks); } catch (e) { Logger.log('Error AI: ' + e.toString()); return { skor: 0, kekurangan: 'Gagal dianalisis', ringkasan: '-' }; } }
